denials.command:
npm run -s story:lint -- the-number --json > $TMPDIR/lint.json 2>/dev/null; node -e '
const j=JSON.parse(require("fs").readFileSync(process.env.TMPDIR+"/lint.json","utf8"));
const arr=Array.isArray(j)?j:(j.findings||j.issues||Object.values(j).flat());
console.log(Object.keys(arr[0]||{}));
const by={};for(const f of arr){if(f.level==="hint"||f.severity==="hint"||f.severity==="info")continue;const o=f.owner||f.fix||"?";(by[o]??=[]).push(f)}
for(const [o,l] of Object.entries(by)){console.log("\n## "+o+" ("+l.length+")");for(const f of l)console.log(" ",f.severity||f.level,f.id||f.check,"·",f.node||"","·",(f.message||f.text||"").slice(0,220))}
'

